<template><section class="module8-plan"><h2>Your Module 8 chapter plan</h2><p>Complete at least two full chapters. Unselected chapters are optional and do not count as unfinished work.</p><article v-for="c in chapters" :key="c.key"><h3>Chapter {{c.number}}: {{c.title}}</h3><p>{{c.why}}</p><ol><li>Read every topic in this chapter.</li><li>Complete its walkthroughs and guided practice.</li><li>Complete the self-check and all assigned Apply tasks.</li><li>Record and submit the required evidence.</li></ol></article></section></template><script setup>import {computed} from 'vue';import {useModule8Preferences} from '../composables/useModule8Preferences.js';const prefs=useModule8Preferences();const chapters=computed(()=>prefs.getChapters().filter(c=>prefs.selectedChapters.value.includes(c.key)));</script><style scoped>.module8-plan{padding:1rem;border:1px solid var(--border);border-radius:.5rem;margin:1rem 0}li,p{line-height:1.6}</style>